    private static void reject(Attempt a,String why)throws Exception{boolean no=false;try{a.run();}catch(Exception expected){no=true;}require(no,why);}
    private static Mind memory()throws Exception{User u=new User();Mind m=new Mind(u);u.setCurrentMind(m);return m;}
    private static Rule raw(Mind m,String text)throws Exception{return (Rule)m.compileLine(text,false,new LinkedList<ITerm>());}
    private static Policy policy(){return new Policy(2000000,1000,1000,64000000,200000);}
    private static Member member(Mind m,int id,boolean local)throws Exception{return new Member(m,ContextProductionInventory.inspect(m,new UUID(0,id),3,local,Collections.emptyList(),1000));}
    private static Source source(Member m,long rule){return new Source(m.inventory.context,m.inventory.revision,rule,m.inventory.localX,"inventory:"+m.inventory.fingerprint);}
    private static SemanticTermSnapshot value(String literal)throws Exception{Mind m=memory();Rule r=raw(m,"!value("+literal+");");return SemanticTermSnapshot.capture(r.getDomain().get(0).getValue(m));}
    private static Model model(List<SemanticTermSnapshot> points,SemanticTermSnapshot other,String[] names,int[] arities,boolean[] truth,Map<Function,Choice> functions){Map<Signature,Relation> rels=new LinkedHashMap<>();for(int i=0;i<names.length;i++)rels.put(new Signature(names[i],arities[i]),new Relation(truth[i],Collections.emptyMap()));return new Model(points,other,rels,functions);}
    private static ContextDependentCandidateInspection.Request append(int rounds,String... text){return new ContextDependentCandidateInspection.Request(new ContextDependentIterationInspection.Request(policy(),10000,rounds),Arrays.asList(text));}
    private static Request request(ContextDependentCandidateInspection.Request append,Map<String,Model> base,Map<String,Model> proposed,int bo,int bf,int po,int pf){return new Request(append,base,proposed,20,100000,bo,bf,po,pf);}
    private static Request request(ContextDependentCandidateInspection.Request append,Map<String,Model> base,Map<String,Model> proposed){return request(append,base,proposed,4000000,4000000,4000000,4000000);}
    private static Map<String,Model> local(Member base,Model model){return Collections.singletonMap(ContextDependentCutInspection.local(base.inventory.context),model);}
    private static ContextDependentRuntimeModelInspection.Request checked(Request q,int shape,int truth){return new ContextDependentRuntimeModelInspection.Request(new ContextDependentRuntimeInspection.Request(q,100000,1000000,4000000,4000000),shape,truth);}
    private static ContextDependentRuntimeModelInspection.Request checked(Request q){return checked(q,4000000,4000000);}
    private static void incompleteRuntime(ContextDependentRuntimeModelInspection.Result r,String phase,String why){require(r.status==ContextDependentRuntimeModelInspection.Status.INCOMPLETE&&r.phase.equals(phase),why+": "+r.phase+"/"+r.reason);require(r.frame==null&&r.projection==null&&r.runtimeObligations==0,"runtime failure exposes no earlier model/projection prefix");}
    private static Map<List<Integer>,Boolean> tuples(int[]... tuples){Map<List<Integer>,Boolean> rows=new LinkedHashMap<>();for(int[] tuple:tuples){List<Integer> key=new ArrayList<>();for(int v:tuple)key.add(v);rows.put(key,true);}return rows;}
    private static Model change(Model m,String name,int arity,Relation relation,Map<Function,Choice> functions){Map<Signature,Relation> rs=new LinkedHashMap<>(m.relations);if(name!=null)rs.put(new Signature(name,arity),relation);return new Model(m.points,m.otherRepresentative,rs,functions==null?m.functions:functions);}
    private static Model actual(Model model,ContextDependentRuntimeModelInspection.Result result,String cut){Map<Function,Choice> fs=new LinkedHashMap<>();for(Map.Entry<Function,Choice> e:model.functions.entrySet())fs.put(result.projection.qualification.reboundFunctions.get(cut).get(e.getKey()),e.getValue());return new Model(model.points,model.otherRepresentative,model.relations,fs);}
